use std::io::{self, Write as _};
use std::path::Path;
use std::process::{Command, Stdio};

use proc_macro2::TokenStream;
use quote::quote;

const HEADER: &str = "\
// Generated by `luck_ast_tools` from the types that derive `Ast`. Run
// `just ast` after changing one.

";

/// A doc comment of this text prints as a blank line, which `quote!` has no
/// other way to write, so the imports keep AGENTS.md's grouping.
const LINE_BREAK: &str = "@@line_break";

/// A blank line before the item that follows.
pub(crate) fn line_break() -> TokenStream {
    quote!(#[doc = #LINE_BREAK])
}

/// `text` as doc comments, one a line, wrapped at the widths the
/// hand-written docs keep.
pub(crate) fn doc(text: &str) -> TokenStream {
    let mut lines: Vec<String> = Vec::new();
    for paragraph in text.split("\n\n") {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        let mut line = String::new();
        for word in paragraph.split_whitespace() {
            if !line.is_empty() && line.len().saturating_add(word.len()) >= DOC_WIDTH {
                lines.push(line);
                line = String::new();
            }
            line.push(' ');
            line.push_str(word);
        }
        lines.push(line);
    }
    quote!(#(#[doc = #lines])*)
}

/// Doc comments wrap before this column, counting from the text after `///`.
const DOC_WIDTH: usize = 72;

/// `tokens` as a formatted file, the way `cargo fmt` leaves it.
///
/// # Errors
///
/// Fails when `tokens` aren't a Rust file, or `rustfmt` can't run or fails.
pub(crate) fn print_rust(tokens: TokenStream, workspace: &Path) -> io::Result<String> {
    let file = syn::parse2::<syn::File>(tokens).map_err(io::Error::other)?;
    let printed = prettyplease::unparse(&file);
    let mut code = String::from(HEADER);
    for line in printed.lines() {
        if line.trim() != format!("///{LINE_BREAK}") {
            code.push_str(line);
        }
        code.push('\n');
    }
    Ok(end_wrapped_calls(&rustfmt(&code, workspace)?))
}

/// Ends with `;` each call rustfmt wrapped in a block.
///
/// rustfmt wraps a match arm too long for its line in a block, and leaves
/// out the `;` clippy's `semicolon_if_nothing_returned` asks for. The only
/// calls an arm here makes alone are a visitor's, which return nothing.
fn end_wrapped_calls(code: &str) -> String {
    let mut fixed = String::with_capacity(code.len());
    let mut lines = code.lines().peekable();
    let mut previous = "";
    while let Some(line) = lines.next() {
        fixed.push_str(line);
        let is_wrapped_call = previous.ends_with("=> {")
            && line.trim_start().starts_with("self.visit_")
            && line.ends_with(')')
            && lines.peek().is_some_and(|next| next.trim() == "}");
        if is_wrapped_call {
            fixed.push(';');
        }
        fixed.push('\n');
        previous = line;
    }
    fixed
}

/// # Errors
///
/// Fails when `rustfmt` can't run or fails.
fn rustfmt(code: &str, workspace: &Path) -> io::Result<String> {
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--config-path"])
        .arg(workspace.join("rustfmt.toml"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    if let Some(mut stdin) = child.stdin.take() {
        stdin.write_all(code.as_bytes())?;
    }
    let output = child.wait_with_output()?;
    if !output.status.success() {
        return Err(io::Error::other(String::from_utf8_lossy(&output.stderr).into_owned()));
    }
    String::from_utf8(output.stdout).map_err(io::Error::other)
}
